// Regenerate `test/spec-conformance/generated.ts` from the bundled OpenAPI spec.
// The generated file is imported by `types.test.ts` to verify our handwritten
// types are structurally compatible with the spec's schemas.

import { writeFile } from 'node:fs/promises'
import { resolve, dirname } from 'node:path'
import { fileURLToPath } from 'node:url'
import openapiTS, { astToString } from 'openapi-typescript'

const __dirname = dirname(fileURLToPath(import.meta.url))
const SPEC = resolve(__dirname, '../tmp/rest-catalog-open-api.yaml')
const OUT = resolve(__dirname, '../test/spec-conformance/generated.ts')

const ast = await openapiTS(new URL(`file://${SPEC}`), {
  // Don't promote fields with `default: ...` to required. The spec relies on
  // explicit `required: [...]` lists, so honor those instead of the default
  // heuristic (which would force callers to specify fields the spec marks optional).
  defaultNonNullable: false,
})
const banner = '// AUTOGENERATED by scripts/gen-spec-types.mjs. Do not edit.\n\n'
await writeFile(OUT, banner + astToString(ast), 'utf-8')

console.log(`Wrote ${OUT}`)
